@push('styles')<style>
.fleet-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:25px}.fleet-head h1{margin:5px 0;font-size:32px}.fleet-head p,.fleet-breadcrumb,.muted{margin:0;color:#64748b}.fleet-breadcrumb{font-size:12px}.fleet-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:22px}.fleet-stat,.fleet-card,.fleet-form{background:#fff;border:1px solid #e2e8f0;border-radius:13px;box-shadow:0 1px 3px #0f172a12}.fleet-stat{padding:19px}.fleet-stat strong{display:block;font-size:29px}.fleet-stat span{color:#64748b;font-size:12px}.fleet-card,.fleet-form{overflow:hidden}.fleet-filters{display:grid;grid-template-columns:2fr repeat(4,minmax(0,1fr)) auto;gap:10px;padding:18px;border-bottom:1px solid #e2e8f0}.fleet-filters input,.fleet-filters select,.fleet-form input,.fleet-form select{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}.fleet-table-wrap,.document-scroll{overflow-x:auto}.fleet-table,.document-table{width:100%;border-collapse:collapse}.fleet-table th,.fleet-table td,.document-table th,.document-table td{padding:14px 18px;text-align:left;border-bottom:1px solid #e2e8f0}.fleet-table th,.document-table th{font-size:11px;text-transform:uppercase;color:#64748b;background:#f8fafc}.unit{display:flex;align-items:center;gap:11px;min-width:170px}.unit-icon{width:40px;height:40px;display:grid;place-items:center;border-radius:9px;background:#E8F5F0;color:var(--green);font-weight:800}.unit small{display:block;color:#64748b}.fleet-badge{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border-radius:99px;font-size:12px;font-weight:700}.fleet-badge.available,.fleet-badge.active,.fleet-badge.valid{background:#dcfce7;color:#166534}.fleet-badge.unavailable,.fleet-badge.inactive{background:#f1f5f9;color:#475569}.fleet-badge.to_renew{background:#fef3c7;color:#92400e}.fleet-badge.expired{background:#fee2e2;color:#991b1b}.fleet-link{color:var(--green);font-weight:700;text-decoration:none}.fleet-pagination{padding:18px}.fleet-detail{display:grid;grid-template-columns:1fr 1.5fr;gap:18px}.fleet-card-head{padding:17px 20px;border-bottom:1px solid #e2e8f0}.fleet-card-head h2{margin:0;font-size:18px}.fleet-card-body{padding:20px}.fleet-info{display:grid;grid-template-columns:repeat(2,1fr);gap:19px}.fleet-info small{display:block;color:#64748b;text-transform:uppercase;font-size:10px;font-weight:700;margin-bottom:5px}.fleet-form-body{padding:24px}.fleet-form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.fleet-field.full{grid-column:1/-1}.fleet-field label{display:block;margin-bottom:7px;font-size:13px;font-weight:700}.fleet-error{display:block;color:#b91c1c;font-size:12px;margin-top:5px}.fleet-errors{margin:0 24px 20px;padding:14px;border-radius:9px;background:#fef2f2;color:#991b1b}.fleet-form-footer{display:flex;justify-content:flex-end;gap:10px;padding:18px 24px;border-top:1px solid #e2e8f0;background:#f8fafc}.required{color:var(--danger)}
@media(max-width:950px){.fleet-summary{grid-template-columns:repeat(2,1fr)}.fleet-filters,.fleet-detail{grid-template-columns:1fr}}@media(max-width:650px){.fleet-head{align-items:flex-start;flex-direction:column}.fleet-summary,.fleet-form-grid,.fleet-info{grid-template-columns:1fr}.fleet-field.full{grid-column:auto}.fleet-form-footer{flex-direction:column-reverse}}
</style>@endpush
@push('styles')<style>
.fleet-stat{position:relative;padding-top:34px}.fleet-stat>span{position:absolute;top:16px;left:19px;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.35px}.fleet-stat strong{color:var(--text)}.fleet-stat small{display:block;margin-top:5px;color:#7b8794;font-size:11px}.fleet-stat.success{border-top:3px solid var(--green)}.fleet-stat.warning{border-top:3px solid var(--gold)}.directory-head{display:flex;justify-content:space-between;align-items:center}.directory-head p{margin:4px 0 0;color:#64748b;font-size:12px}.fleet-filters{align-items:end}.fleet-filters label{display:block;margin-bottom:6px;color:#475569;font-size:11px;font-weight:800}.filter-actions{display:flex;align-items:center;gap:11px}.filter-actions a{color:#64748b;font-size:12px;font-weight:700;text-decoration:none}.document-count{font-size:12px;color:#475569}.empty-state{padding:32px;text-align:center}.empty-state strong,.empty-state span{display:block}.empty-state span{margin-top:6px;color:#64748b;font-size:13px}.form-section+.form-section{margin-top:30px;padding-top:27px;border-top:1px solid #e2e8f0}.form-section-head{display:flex;gap:13px;margin-bottom:20px}.form-section-head>span{width:31px;height:31px;display:grid;place-items:center;flex:none;border-radius:50%;background:#E8F5F0;color:var(--green);font-size:11px;font-weight:900}.form-section-head h2{margin:0 0 4px;font-size:18px}.form-section-head p{margin:0;color:#64748b;font-size:12px}.fleet-field>small{display:block;margin-top:6px;color:#7b8794;font-size:11px;line-height:1.4}
@media(max-width:950px){.fleet-filters{grid-template-columns:repeat(2,1fr)}.filter-search,.filter-actions{grid-column:1/-1}}@media(max-width:650px){.fleet-filters{grid-template-columns:1fr}.filter-search,.filter-actions{grid-column:auto}.filter-actions{align-items:stretch;flex-direction:column;gap:12px}.fleet-head .btn{width:100%}.fleet-form-body,.fleet-form-footer,.fleet-filters{padding:16px}.fleet-form-footer{gap:12px}.fleet-filters input,.fleet-filters select,.fleet-form input,.fleet-form select{min-height:44px;font-size:16px}.fleet-field label{font-size:14px}.fleet-table{min-width:720px}.fleet-form-footer .btn,.fleet-head .btn,.filter-actions .btn,.filter-actions a,.fleet-link{min-height:44px;display:inline-flex;align-items:center;justify-content:center}}
</style>@endpush
